/**
 * The Retrace document format. Everything here is plain JSON so projects can be
 * saved to disk, diffed, and generated by scripts or AI agents.
 */

import type { BrushStyle } from './brushes';

/** x, y in project pixels; pressure 0..1; t = ms since the stroke started. */
export type Point = [x: number, y: number, pressure: number, t: number];

export interface Stroke {
  id: string;
  points: Point[];
  color: string;
  /** Nib diameter in project pixels. */
  size: number;
  /** Defaults to 'marker'. */
  brush?: BrushStyle;
  /** Mouse/touch/generated input has no real pressure, so derive it from velocity instead. */
  simulatePressure: boolean;
}

export interface Step {
  id: string;
  /** Optional human/AI-readable note, e.g. "draw the CPU". */
  label?: string;
  strokes: Stroke[];
  /** Pause after this step finishes drawing, in ms. */
  hold: number;
}

export interface Project {
  version: 1;
  width: number;
  height: number;
  background: string;
  /** Playback speed multiplier applied to recorded drawing motion. */
  speed: number;
  /** Steps are cumulative: showing step N shows the strokes of steps 0..N. */
  steps: Step[];
}

/** Ink colors tuned for the off-white background: ink, pencil gray, then accents. */
export const PALETTE = ['#1e1e1e', '#868e96', '#f59f00', '#1c7ed6', '#e03131', '#2f9e44'] as const;
export const SIZES = { thin: 4, medium: 7, bold: 12 } as const;
export const DEFAULT_HOLD = 400;

export function uid(): string {
  return Math.random().toString(36).slice(2, 10);
}

export function createStep(init: Partial<Omit<Step, 'id'>> = {}): Step {
  return { id: uid(), strokes: [], hold: DEFAULT_HOLD, ...init };
}

export function createProject(init: Partial<Omit<Project, 'version' | 'steps'>> = {}): Project {
  return {
    version: 1,
    width: 1920,
    height: 1080,
    background: '#f8f9fa',
    speed: 1,
    ...init,
    steps: [createStep()],
  };
}

/** Light validation for files coming from disk or another program. */
export function parseProject(data: unknown): Project {
  const p = data as Partial<Project> | null;
  if (!p || p.version !== 1 || !Array.isArray(p.steps) || p.steps.length === 0) {
    throw new Error('Not a Retrace project (expected version 1 with at least one step)');
  }
  for (const step of p.steps) {
    if (!Array.isArray(step.strokes)) throw new Error(`Step ${step.id} has no strokes array`);
  }
  return {
    ...createProject(),
    ...p,
    speed: typeof p.speed === 'number' && p.speed > 0 ? p.speed : 1,
  } as Project;
}

export function strokeDuration(stroke: Stroke): number {
  return stroke.points.length ? stroke.points[stroke.points.length - 1][3] : 0;
}
